import assert from 'node:assert/strict';
import { test } from 'node:test';

import { schnorr } from '@noble/curves/secp256k1.js';
import { bech32m, hex } from '@scure/base';
import { SigHash, Transaction } from '@scure/btc-signer/transaction.js';

import {
  createMnemonic,
  estimatePaymentVsize,
  normalizeMnemonic,
  openPearlWallet,
  validateTestnetAddress,
  verifyPearlPrevout,
} from '../src/pearl-keys.ts';

// Public Testnet2 plain-address vectors generated by PocketPRL with Oyster.
// https://github.com/pocketprl/pocketprl/blob/be117e90180648fca2e615df3c107bb9c58673e5/app/src/test/resources/pearl_vectors.json
const mnemonic = 'abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon about';
const receive = 'tprl1p8wpt9v4frpf3tkn0srd97pksgsxc5hs52lafxwru9kgeephvs7rqm5v93u';
const recipient = 'tprl1p90h6z3p36n9hrzy7580h5l429uwchyg8uc9sz4jwzhdtuhqdl5eql4fqfa';
const change = 'tprl1p6uav7en8k7zsumsqugdmg5j6930zmzy4dg7jcddshsr0fvxlqx7q64nev7';

function fixture(wallet, amountGrains, branch = 0, coinbase = true) {
  const scriptHex = wallet.scriptHex(branch);
  const transaction = new Transaction({ version: 1 });
  transaction.addOutput({ amount: BigInt(amountGrains), script: hex.decode(scriptHex) });
  transaction.addInput({
    txid: (coinbase ? '0' : 'a').repeat(64),
    index: coinbase ? 0xffffffff : 0,
    finalScriptSig: coinbase ? hex.decode('020603') : undefined,
  });
  return {
    txid: transaction.id,
    vout: 0,
    amountGrains,
    scriptHex,
    rawTxHex: transaction.hex,
    branch,
  };
}

test('matches Oyster Testnet2 plain Taproot address fixtures', () => {
  assert.equal(createMnemonic(new Uint8Array(16)), mnemonic);
  assert.equal(normalizeMnemonic(` ${mnemonic.toUpperCase().replaceAll(' ', '\n')} `), mnemonic);
  assert.equal(normalizeMnemonic(mnemonic.replace('about', 'abandon')), null);
  assert.throws(() => openPearlWallet('secret'));

  const wallet = openPearlWallet(mnemonic);
  assert.equal(wallet.address(), receive);
  assert.equal(wallet.address(0, 1), recipient);
  assert.equal(wallet.address(1), change);
  assert.throws(() => wallet.address(0, 0x80000000));
  wallet.close();
  assert.throws(() => wallet.address());
});

test('accepts canonical Testnet2 addresses and rejects invalid checksums and networks', () => {
  const words = bech32m.decode(receive).words;
  const merkleRoot = bech32m.encode('tprl', [2, ...bech32m.toWords(new Uint8Array(32).fill(17))]);
  assert.equal(validateTestnetAddress(receive.toUpperCase()), receive);
  assert.equal(validateTestnetAddress(merkleRoot), merkleRoot);
  assert.equal(validateTestnetAddress(receive.slice(0, -1) + 'q'), null);
  assert.equal(validateTestnetAddress(bech32m.encode('prl', words)), null);
  assert.equal(validateTestnetAddress(bech32m.encode('tprl', [3, ...words.slice(1)])), null);
  assert.equal(validateTestnetAddress('tprl' + receive.slice(4).toUpperCase()), null);
});

test('authenticates raw prevouts and identifies coinbase inputs', () => {
  const wallet = openPearlWallet(mnemonic);
  try {
    const coinbase = fixture(wallet, 400_000);
    assert.deepEqual(verifyPearlPrevout(coinbase), { coinbase: true });
    assert.deepEqual(verifyPearlPrevout(fixture(wallet, 500_000, 1, false)), { coinbase: false });
    for (const change of [
      { txid: 'f'.repeat(64) },
      { vout: 1 },
      { amountGrains: 399_999 },
      { scriptHex: wallet.scriptHex(1) },
      { rawTxHex: 'feedface' },
    ]) {
      assert.throws(() => verifyPearlPrevout({ ...coinbase, ...change }));
    }
  } finally {
    wallet.close();
  }
});

test('signs a two-input exact-output payment, with fee and per-input signatures verified', () => {
  const wallet = openPearlWallet(mnemonic);
  try {
    const inputs = [fixture(wallet, 400_000), fixture(wallet, 500_000, 1, false)];
    const payment = {
      inputs,
      recipient,
      amountGrains: 700_000,
      changeGrains: 199_500,
      feeGrains: 500,
      entropy: new Uint8Array(32).fill(7),
    };
    const signed = wallet.signPayment(payment);
    const transaction = Transaction.fromRaw(hex.decode(signed.hex));
    assert.equal(transaction.id, signed.txid);
    assert.equal(transaction.version, 1);
    assert.equal(signed.vsize, 212);
    assert.equal(estimatePaymentVsize(2, true), signed.vsize);
    assert.equal(estimatePaymentVsize(1, false), 111);
    assert.equal(transaction.getOutput(0).amount, 700_000n);
    assert.equal(transaction.getOutput(1).amount, 199_500n);
    assert.equal(hex.encode(transaction.getOutput(1).script), wallet.scriptHex());

    const scripts = inputs.map(({ scriptHex }) => hex.decode(scriptHex));
    const amounts = inputs.map(({ amountGrains }) => BigInt(amountGrains));
    for (const position of inputs.keys()) {
      const { finalScriptWitness } = transaction.getInput(position);
      assert.equal(finalScriptWitness.length, 1);
      assert.equal(finalScriptWitness[0].length, 64);
      const digest = transaction.preimageWitnessV1(position, scripts, SigHash.DEFAULT, amounts);
      assert.ok(schnorr.verify(finalScriptWitness[0], digest, scripts[position].subarray(2)));
    }

    assert.throws(() => wallet.signPayment({ ...payment, feeGrains: 499 }), /fee/);
    assert.throws(() => wallet.signPayment({ ...payment, inputs: [inputs[0], inputs[0]] }), /twice/);
    assert.throws(() => wallet.signPayment({
      ...payment, inputs: [inputs[0], { ...inputs[1], branch: 0 }],
    }), /does not belong/);
  } finally {
    wallet.close();
  }
});

test('matches Oyster’s BIP341 digest for its Testnet2 plain Taproot spend vector', () => {
  const transaction = Transaction.fromRaw(hex.decode(
    '020000000208e45d0ca38a3abab9de3633d7c213a52c8297a0e3fd0575424ca3817d368eda0100000000ffffffff' +
    'd50ff59c639fe75fbb63acf0f78d0025693d51d8f2c5ba143260324590daa0f80200000000ffffffff02' +
    '0046c32300000000225120208ecde3fffd5d51474e1414ffd3e92460962cfe78e9b0b4a7a37cb1a32e2fc2' +
    '802b530b000000002251209450706c1949cffff61606fb1a7d6735c80b2793e5f4312a45c692cbd98c862400000000'
  ));
  const scripts = [
    '512015fd41acdeafcf4628c048e9cfcfdbb92af61002de8fbfd493460042b1e7a2c0',
    '5120cabac13996a24ccecf98761c9b0edf1764bd0cea42925c82cbdaf8658b61b07d',
  ].map(script => hex.decode(script));
  const digests = [
    'd0ab519a085e016d4d1b8971882be143e8eb94914e2d78c5427811d814aca0d0',
    'e0b8f5edb2fccd456e47017a92880f92b03242e8dad19e1a0cc2165348750af6',
  ];

  assert.equal(transaction.id, '4bcb4beedfab4b08a1ddf106123f4619384ff422c149b5ee197e6b373bf40dee');
  for (const [position, digest] of digests.entries()) {
    assert.equal(
      hex.encode(transaction.preimageWitnessV1(position, scripts, SigHash.DEFAULT, [500_000_000n, 300_000_000n])),
      digest
    );
  }
});

test('serializes a Testnet2 Merkle-root recipient as a v2 witness program', () => {
  const wallet = openPearlWallet(mnemonic);
  try {
    const program = new Uint8Array(32).fill(17);
    const recipient = bech32m.encode('tprl', [2, ...bech32m.toWords(program)]);
    const signed = wallet.signPayment({
      inputs: [fixture(wallet, 400_000)],
      recipient,
      amountGrains: 399_650,
      changeGrains: 0,
      feeGrains: 350,
      entropy: new Uint8Array(32).fill(8),
    });
    const transaction = Transaction.fromRaw(hex.decode(signed.hex), { allowUnknownOutputs: true });
    assert.equal(transaction.outputsLength, 1);
    assert.equal(hex.encode(transaction.getOutput(0).script), '5220' + hex.encode(program));
    assert.equal(signed.vsize, estimatePaymentVsize(1, false));
  } finally {
    wallet.close();
  }
});
